//! Cargo-driven `autochk.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is autochk-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_NtProcessStartup@4"),
        "x86_64" => ("x86_64-pc-windows-gnu", "NtProcessStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "NtProcessStartup"),
        o => panic!("autochk-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["sdk/lib/nt/libnt.a", "sdk/lib/fslib/vfatlib/libvfatlib.a", "sdk/lib/fslib/vfatxlib/libvfatxlib.a", "sdk/lib/fslib/cdfslib/libcdfslib.a", "sdk/lib/fslib/vfatlib/libvfatlib_rust.a", "sdk/lib/fslib/vfatxlib/libvfatxlib_rust.a", "engine:chkstk"],
        "x86_64" => &["sdk/lib/nt/libnt.a", "sdk/lib/fslib/vfatlib/libvfatlib.a", "sdk/lib/fslib/vfatxlib/libvfatxlib.a", "sdk/lib/fslib/cdfslib/libcdfslib.a", "sdk/lib/fslib/vfatlib/libvfatlib_rust.a", "sdk/lib/fslib/vfatxlib/libvfatxlib_rust.a", "engine:chkstk"],
        "aarch64" => &["sdk/lib/nt/libnt.a", "sdk/lib/fslib/vfatlib/libvfatlib.a", "sdk/lib/fslib/vfatxlib/libvfatxlib.a", "sdk/lib/fslib/cdfslib/libcdfslib.a", "sdk/lib/fslib/vfatlib/libvfatlib_rust.a", "sdk/lib/fslib/vfatxlib/libvfatxlib_rust.a", "engine:chkstk"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("autochk-rust")
        .c_from_compile_db("autochk_shims", &["base/system/autochk/rust_varargs_shim.c"])
        .resource_from_rc("base/system/autochk/autochk.rc", "autochk_res")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "native:5.01".into(),
        });
}
